/** M4 recipe library (supabase/seed.sql): recipe n, its revision, and ingredient line (recipe, position). */
const pad = (n: number, w: number) => String(n).padStart(w, "0");
export const M4 = {
  recipe: (n: number) => `00000000-0000-4000-8000-00000043${pad(n, 4)}`,
  rev: (n: number) => `00000000-0000-4000-8000-00000044${pad(n, 4)}`,
  line: (recipe: number, position: number) => `00000000-0000-4000-8000-00000045${pad(recipe, 2)}${pad(position, 2)}`,
  ingredientRev: (n: number) => `00000000-0000-4000-8000-00000042${pad(n, 4)}`,
  scramble: 1, oats: 2, yogurtBowl: 3, bakedEggs: 4, chana: 5, paneerCurry: 6, dal: 7, stirFry: 8, noodles: 9, quinoaBowl: 10, crispyChickpeas: 11,
} as const;
